1	"use server";
2	
3	/**
4	 * Accepts an invitation token and creates the membership.
5	 *
6	 * Owner D. Runs for a signed-in user who is *not yet* a member of the target
7	 * org, so there is no `Actor` to resolve and the action cannot use
8	 * `withAction()`. The seat quota is re-checked at acceptance time because the
9	 * organization may have filled up since the invitation was sent.
10	 *
11	 * Must call (do not reimplement): acceptInvitationTokenSchema, getPlanLimits
12	 */
13	
14	import { PlanLimitError, UnauthorizedActionError } from "@/actions/_lib/action-errors";
15	import { getPlanLimits } from "@/config/plan-limits";
16	import { toActionResult } from "@/lib/errors";
17	import { getSessionPrincipal } from "@/lib/session";
18	import { acceptInvitationTokenSchema } from "@/schemas/invitation";
19	import { acceptInvitation } from "@/server/services/invitation-service";
20	import { resolveActor } from "@/server/services/member-service";
21	import { getOrganizationSummary } from "@/server/services/organization-service";
22	import type { ActionResult } from "@/types/api";
23	import type { Member } from "@/types/member";
24	
25	export async function acceptInvitationAction(raw: unknown): Promise<ActionResult<Member>> {
26	  const parsed = acceptInvitationTokenSchema.safeParse(raw);
27	  if (!parsed.success) {
28	    return toActionResult(parsed.error);
29	  }
30	
31	  try {
32	    const principal = await getSessionPrincipal();
33	    if (principal === null) {
34	      throw new UnauthorizedActionError("Sign in before accepting an invitation.");
35	    }
36	
37	    const member = await acceptInvitation(principal.userId, parsed.data);
38	    await assertSeatAvailable(member);
39	
40	    return { ok: true, data: member, submittedAt: new Date().toISOString() };
41	  } catch (error) {
42	    return toActionResult(error);
43	  }
44	}
45	
46	/**
47	 * Confirms the newly created membership still fits the plan. Reading usage
48	 * requires an actor inside the org, which only exists once the membership row
49	 * has been written — hence the check runs after `acceptInvitation`.
50	 */
51	async function assertSeatAvailable(member: Member): Promise<void> {
52	  const actor = await resolveActor(member.userId, member.orgId);
53	  if (actor === null) {
54	    throw new UnauthorizedActionError("That invitation is no longer valid.");
55	  }
